<main class="main" id="classes-with-subjects"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><nav class="breadcrumb" aria-label="Breadcrumb"><a href="<?= url('/admin/dashboard') ?>">Dashboard</a><i data-lucide="chevron-right"></i><span>Subjects</span><i data-lucide="chevron-right"></i><span aria-current="page">Classes With Subjects</span></nav><h1>Classes With Subjects</h1><p>Review subject assignments for every class</p></div><a class="btn btn--primary" href="<?= url('/admin/subjects/assign') ?>"><i data-lucide="plus"></i>Assign Subjects</a></header><section class="module-card"><header class="module-card__header"><div><h2>Class &amp; Subject Directory</h2><p>Persisted subject associations by class</p></div></header><div class="module-card__body"><?php if(!$classes):?><div class="compact-empty"><div><span class="compact-empty__icon"><i data-lucide="book-open"></i></span><h3>No Classes Found</h3><p>Create a class before assigning subjects.</p></div></div><?php else:?><table class="responsive-table"><thead><tr><th>Class</th><th>Subjects</th></tr></thead><tbody><?php foreach($classes as $class):?><tr><td data-label="Class"><?= e($class['name']) ?></td><td data-label="Subjects"><?php if(!$class['subjects']):?>No subjects assigned<?php else:?><?php foreach($class['subjects'] as $subject):?><span class="status-badge"><?= e($subject['name']) ?> (<?= e($subject['marks']) ?>)</span> <?php endforeach ?><?php endif ?></td></tr><?php endforeach ?></tbody></table><?php endif ?></div></section></div></div></main>
